      "text": "Ο Διενής στην λαϊκήν παράδοσην παρουσιάζεται ως ένας θρυλικός ήρωας με υπερφυσικές δυνάμεις. Σύμφωνα με την φαντασίαν του λαού, ήταν τζ̆είνος που, όπως ετζ̆υνήαν Σαρατζ̆ηνούς, εκούμπησεν το σ̆έριν του πά’ στον βράχον τζ̆αι άφηκεν αποτύπωμαν τα πέντε του δάχτυλα στην κορυφήν. Έτσι έπιασεν το όνομαν της η οροσειρά του Πενταδαχτύλου. Τζ̆είνος ήταν τζ̆αι που επέταξεν την Πέτραν του Ρωμιού κατά των Σαρατζ̆ηνών πειρατών που εθέλαν ν’ αποβιβαστούν στην Κύπρον, για να τους καταστρέψει τα καράφκια τους. Τζ̆είνος ήταν επίσης που επολέμαν τον Χάρον στα μαρμαρένια αλώνια «τρεις νύχτες, τρεις ημέρες». Οι μέχρι τώρα ηχογραφήσεις (επιτόπιες τζ̆αι μη) τούντου αφηγηματικού τραουθκιού αφορούν την μάχην με τον Χάρον, όταν κατεβαίννει ο Χάρος στο παναΰριν τζ̆αι γυρεύκει «τον κάλλιον μας» να τον πολεμήσει τζ̆αι να τον πάρει. Το απόσπασμαν που εθκιάλεξα να τραουδήσω ακολουθεί χρονικά την μάχην του Διενή με τον Χάρον· εν’ η ώρα που ο ήρωας ψυχομασ̆εί."
