      "text": "Η «Φωνή Καταραμένη» εν’ μια που τες φωνές της Κύπρου. «Φωνές» στην κυπριακήν παραδοσιακήν μουσικήν ονομάζουμεν πλέον συγκεκριμένες μελωδίες, πάνω στες οποίες τραουθκιούνται δίστιχα ή ολιγόστιχα. Ο στίχος τους, δηλαδή, υποτάσσεται στην υπάρχουσαν μελωδίαν. Η «Φωνή Καταραμένη» εν’ φωνή της επαρχίας Πάφου, που ηχογραφήθηκεν ανά διαστήματα με διαφορετικές ονομασίες. Ηχογραφήθηκεν που την λαογραφικήν αποστολήν της Ακαδημίας Αθηνών υπό τους Σπυριδάκη και Καρακάση το 1960 σε επιτόπιαν ηχογράφησην στην Γιόλου ως «Φωνή Γιολίτισσα». Μουσικήν επαίζαν οι Αργύρης Σάββα (φκιολίν) τζ̆αι Κυριάκος Παρπέρης ή Βάκανος (λαούτον), τζ̆αι ετραγουδούσαν οι Δημήτρης Φεττάς, Χαράλαμπος Παναγιώτου τζ̆αι Νεόφυτος Χατζ̆ηνικηφόρου. Ακολούθησεν η επιτόπια μουσική αποστολή του Πελοποννησιακού Λαογραφικού Ιδρύματος (ΠΛΙ· 1978-85), υπό τον Φοίβον Ανωγειανάκην, που την εκατέγραψεν με τον τίτλον «Ερωτικά» στο Νιον Χωρκόν. Μουσικοί τότε ήταν οι Χαμπής Θεωρή (φωνή τζ̆αι ταμπουτσ̆ιά) που το Νιον Χωρκόν τζ̆αι Χαμπής Λαζάρου που την Γιόλου (μετέπειτα κάτοικος Νιου Χωρκού· φκιολίν). Ο Χρήστος Σίκκης εσυμπεριέλαβεν την το 1998 ως «Φωνήν Πόλης Χρυσοχούς» στην συλλογήν Έλληνες Ακρίτες – Κύπρος (1998). Το 2008 ο Μιχάλης Ττερλικκάς εκατέγραψεν την στην δισκογραφικήν του δουλειάν Κυπραία Φωνή – Καλώς ήρταν οι ξένοι μας (2008), με τον τίτλον «Φωνή Καταραμένη»."
