      "text": "Ο Μιχάλης Ττερλικκάς, στον δίσκον του Κυπραία Φωνή – Στ’ αγνάρκα των τζ̆αιρών (2002), ηχογράφησεν τούντην φωνήν ως «Φωνή Κωμήτισσα». Εκάμαμεν μιαν κουβέντα με τον Αντώνην Πουλλήν που την Αγιάν Μαρίναν της Σ̆σ̆υλλούρας, γιον του Τζ̆ιαννή Πουλλή (περισσότερες πληροφορίες για τον Τζ̆ιαννήν στες σημειώσεις του τραουθκιού {a song-14}Φωνή Μαρινιωτού{/a}), στο σπίτιν του. Άμαν είπαμεν τες κουβέντες μας, εξεκίνησεν να τραουδά. Μετά που μου ετραούδησεν την «Φωνήν την Μαρινιωτούν», ερώτησεν με αν θέλω να μου πει τζ̆αι μιαν «Καρπασιτούν». Επαραξένεψεν με, γιατί η φωνή που μου ετραούδησεν εν ήταν η γνωστή «Καρπασίτισσα Φωνή» όπως την ήξερα, αλλά η «Κωμήτισσα», όπως την έγραψεν ο Ττερλικκάς στον δίσκο του. Μιλώντας για τούτον με τον κύριον Μιχάλην, είπεν μου ότι εσυνάντησεν παρόμοιαν σύγχυσην όταν εκάμνεν ο ίδιος συνέντευξην του Τζ̆ιαννή:"
