      "text": "Έτσι μου την είπε τζ̆’ εμέναν ο γέρος. Τζ̆’ εγώ, επειδή είμαι που την περιοχήν [Καπούτιν του Μόρφου] […] υπέθεσα ότι έρκετουν που το χωρκόν Καρπάσ̆ια, που ήταν δίπλα που την Αγιάν Μαρίναν. Τυχαία μιαν ημέραν με τον Μιχαλάκην Ηλία – γιον του Νίκου Ηλία, φκιολάρη που την Κώμαν του Γιαλού – εκάμναμεν πρόβαν δαμαί τζ̆’ έπαιξεν μου μιαν μελωδίαν τζ̆’ επαρέπεμψεν με στην Καρπασίτιτζ̆ην που μου είπεν ο Τζ̆ιαννής. Είπεν μου επαίζαν την εις το χωρκόν του. Ήβρα μες το βιβλίον του Σώζου του Τομπόλη[^1] την «Φωνήν Κωμήτισσαν», τζ̆’ έμοιαζεν πολλά με την φωνήν του Τζ̆ιαννή. Με κάποιον τρόπον είσ̆εν δίκαιον δηλαδή [ο Τζ̆ιαννής], διότι εν’ μια φωνή που το Καρπάσιν. Τωρά πώς και γιατί στην Αγιάν Μαρίναν, κάποιος που τούτους [που την Αγιάν Μαρίναν] θα εθήτευσεν στην Καρπασίαν τζ̆’ έμαθεν την τζ̆’ εμάθαν την ούλοι οι χωρκανοί […]. Τζ̆αι όντως εγιώ βρίσκω ότι μοιάζει τζ̆αι με μιαν φωνήν που τραουδά ο Κκεμάλης που την Γαληνόπωρνην [χωρκόν στην περιοχήν Καρπασίας][^2]. Ερώτησα τζ̆αι τον Γιώργον Πουλλήν, γιον του Τζ̆ιαννή, αν ήξερεν γιατί την «Κωμήτισσαν» λαλούν την «Καρπασίτισσαν» στην Αγιάν Μαρίναν τζ̆αι είπε μου ότι τον Τζ̆ιαννήν εκαλούσαν τον να κάμνει γάμους στην περιοχή της Καρπασίας. Πιθανόν ο ίδιος ο Τζ̆ιαννής να εμετάφερεν την μελωδίαν στην Αγιάν Μαρίναν. Ο αρφός του, Μιχάλης Πουλλής, θθυμάται πως πολλοί χωρκανοί του στην Αγιάν Μαρίναν είχαν οικονομικές σχέσεις με την περιοχήν της Καρπασίας τζ̆’ εμεταφέραν άσ̆ερον τζ̆αι κόπριν στα χωράφκια/περβόλια των Καρπασιτών. Σύμφωνα με τον Μιχάλην, πιθανόν κάποιος μέσω τούντου εμπορίου να άκουσε την «Κωμήτισσαν», να του άρεσεν τζ̆αι να την έφερεν στην Αγιάν Μαρίναν. Πάντως η «Κωμήτισσα» ήταν αρκετά διαδεδομένη στην Αγιάν Μαρίναν, όπως μου είπεν ο κύριος Γιώργος, τζ̆’ ετραουδούσαν την πολλοί. Αναφορά μου για τούτην την ηχογράφησην εν’ η ερμηνεία του Τζ̆ιαννή Πουλλή, όπως τον εκατέγραψεν ο γιος του Γιώργος σε μαγνητόφωνον στο σπίτι του στο Έτμοντον στο Λονδίνον το 1968.",
