      "text": "Εδιασκεύασα τούντο κομμάτιν σε ρυθμόν 9/8 (αντί τον σύνθετον 18/8 (7/8 τζ̆αι 11/8) ρυθμόν που το έγραψεν στο ΡΙΚ ο Καλλίνικος) τζ̆αι έδωκα έμφασην σε τούντην ρυθμικήν αγωγήν που ένιωθα να υποβόσκει άμαν το ετραούδουν. Εχρησιμοποιήθηκεν λύρα αντί φκιολίν τζ̆αι θκυο λαούτα – έναν κρητικόν τζ̆αι έναν στεριανό. Η μελωδία στην λύραν τζ̆αι το μελωδικόν λαούτον είναι επίσης ελαφρώς παραλλαγμένη που την καταγραφήν του Καλλίνικου. Σε μιαν πρόβαν με τον Στέλιον, άμαν του έδειξα το τραγούδιν τζ̆’ επαίξαμεν το λλίον, εσυνέχισεν μετά τα λόγια με έναν οργανικόν σκοπόν που έγραψεν ο ίδιος. Ενθουσιάστηκα άμαν τον άκουσα. Ήταν λες τζ̆αι τούτος ο σκοπός του εγράφτηκεν κατά παραγγελίαν για την «Λενούν». Έτσι υιοθετήθηκεν το οργανικόν του Στέλιου ως κομμάτιν της διασκευής μας. Όπως τζ̆αι ο «Σκλάβος», έτσι τζ̆αι τούτη η διασκευή έσ̆ει έναν αέραν που κοντινές σε μας μουσικές παραδόσεις τζ̆αι δεν θα την εχαραχτήριζα αυστηρά κυπριακήν, παρόλον που εχρησιμοποιήσαμεν την ερμηνείαν του Καλλίνικου ως βασικήν μας αναφοράν."
